export type StreamThreadRunDto = {
    /**
     * Graph state input (e.g. new messages). Omit when only sending `command` (e.g. HITL resume after interrupt).
     */
    input?: ThreadInputDto;
    /**
     * Run command forwarded as-is (e.g. `{ "resume": { "decisions": [...] } }` for human-in-the-loop). Required when resuming without new messages.
     */
    command?: {
        [key: string]: unknown;
    };
    /**
     * Stream modes
     */
    stream_mode?: Array<string>;
    /**
     * Stream subgraphs
     */
    stream_subgraphs?: boolean;
    /**
     * Stream resumable
     */
    stream_resumable?: boolean;
    /**
     * Assistant ID
     */
    assistant_id?: string;
    /**
     * Action on disconnect
     */
    on_disconnect?: string;
    /**
     * Workflow ID (agent workflow) to use for this conversation
     */
    workflowId?: string;
    /**
     * Optional model id override for this run (session-scoped). When set, wins over the agent workflow default model.
     */
    model?: string;
    /**
     * Optional reasoning effort override for this run (session-scoped). `none` disables workflow default reasoning. low|medium|high when the model supports reasoning_effort.
     */
    reasoningEffort?: 'none' | 'low' | 'medium' | 'high';
};

export type ThreadInputDto = {
    /**
     * Messages array
     */
    messages: Array<MessageDto>;
};

export type MessageDto = {
    /**
     * Message ID
     */
    id?: string;
    /**
     * Message type
     */
    type: string;
    /**
     * Message content
     */
    content: Array<MessageContentDto>;
};

export type MessageContentDto = {
    /**
     * Content type
     */
    type: 'text' | 'image_url';
    /**
     * Text content
     */
    text?: string;
    /**
     * Image URL block (when type is image_url)
     */
    image_url?: ImageUrlDto;
};

export type ImageUrlDto = {
    /**
     * Image URL (e.g. file download URL or data URL)
     */
    url: string;
};

export type SearchThreadsDto = {
    /**
     * Maximum number of results to return
     */
    limit?: number;
    /**
     * Number of results to skip
     */
    offset?: number;
    /**
     * Sort by field (default: updatedAt for last activity first)
     */
    sortBy?: 'threadId' | 'status' | 'createdAt' | 'updatedAt';
    /**
     * Sort order
     */
    sortOrder?: 'asc' | 'desc';
};

