export type CreateMcpServerDto = {
    /**
     * Name (slug): lowercase letters, numbers, hyphens. Unique per project.
     */
    name: string;
    /**
     * Description of the MCP server
     */
    description?: string;
    /**
     * Mode of the MCP server: NORMAL (specific tools) or META (meta tools only)
     */
    mode?: 'NORMAL' | 'META';
    /**
     * Meta mode only: true = discovery limited to selected tools; false = exclude those tools from discovery.
     */
    discoveryToolsWhitelist?: boolean;
    /**
     * Tool slugs: NORMAL = agent tool set; META = discovery filter list.
     */
    selectedTools?: Array<string>;
    /**
     * Whether the MCP server is public
     */
    isPublic?: boolean;
    /**
     * Configuration for the MCP server (endpoint, authToken, etc.)
     */
    config?: {
        [key: string]: unknown;
    };
    /**
     * External MCP configs (name, url, headers?, tools), same as workflow.
     */
    externalMcpConfigs?: Array<string>;
    /**
     * OAuth return URL after a toolkit connection. Empty string clears.
     */
    connectionCallbackUrl?: string;
};

export type UpdateMcpServerDto = {
    /**
     * Name (slug): lowercase letters, numbers, hyphens. Unique per project.
     */
    name?: string;
    /**
     * Description of the MCP server
     */
    description?: string;
    /**
     * Mode of the MCP server: NORMAL (specific tools) or META (meta tools only)
     */
    mode?: 'NORMAL' | 'META';
    /**
     * Meta mode: true = whitelist discovery to selected tools; false = blacklist those slugs.
     */
    discoveryToolsWhitelist?: boolean;
    /**
     * Tool slugs (NORMAL = fixed set; META = discovery filter). Same as create.
     */
    selectedTools?: Array<string>;
    /**
     * Whether the MCP server is public
     */
    isPublic?: boolean;
    /**
     * Configuration for the MCP server (endpoint, authToken, etc.)
     */
    config?: {
        [key: string]: unknown;
    };
    /**
     * External MCP configs (name, url, headers?, tools). Omit to leave unchanged.
     */
    externalMcpConfigs?: Array<string>;
    /**
     * OAuth return URL after a toolkit connection. Empty string clears.
     */
    connectionCallbackUrl?: string;
};

